**За скин внутри Telegram Mini App нужно принимать Stars (`XTR`), а не TON.** Это цифровой товар; Telegram прямо запрещает криптовалюту для таких покупок. Ниже пример за **100 Stars — это условная цена, не эквивалент 2 TON**. [Правило Telegram](https://core.telegram.org/bots/payments-stars#q-can-i-accept-payment-in-cryptocurrency-instead-of-telegram-stars).

Фронтенд:

```html
<script src="https://telegram.org/js/telegram-web-app.js"></script>
<button id="buy">Купить скин — 100 ⭐</button>
<p id="status"></p>

<script>
const tg = window.Telegram.WebApp;
tg.ready();

document.querySelector("#buy").onclick = async () => {
  const button = document.querySelector("#buy");
  button.disabled = true;

  try {
    const response = await fetch("/api/skin/invoice", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ initData: tg.initData })
    });

    if (!response.ok) throw new Error("Не удалось создать счёт");
    const { url } = await response.json();

    tg.openInvoice(url, () => {
      button.disabled = false;
      // Здесь перечитайте инвентарь с сервера, при необходимости с опросом.
      // Статус callback не даёт права самостоятельно выдать скин.
      document.querySelector("#status").textContent =
        "Статус покупки проверяется на сервере";
    });
  } catch (error) {
    button.disabled = false;
    document.querySelector("#status").textContent = error.message;
  }
};
</script>
```

Бэкенд: Node.js + Express. `db` ниже — адаптер вашей **постоянной БД**; требования к его операциям приведены после кода.

```js
import express from "express";
import {
  createHmac, timingSafeEqual, randomUUID
} from "node:crypto";

const app = express();
app.use(express.json({ limit: "16kb" }));

const TOKEN = process.env.BOT_TOKEN;
const WEBHOOK_SECRET = process.env.WEBHOOK_SECRET;
const PRICE = 100; // Целое количество Stars, задаётся сервером.

if (!TOKEN || !WEBHOOK_SECRET) throw new Error("Missing configuration");

const route = fn => (req, res, next) =>
  Promise.resolve(fn(req, res)).catch(next);

async function bot(method, body) {
  const response = await fetch(
    `https://api.telegram.org/bot${TOKEN}/${method}`,
    {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(body),
      signal: AbortSignal.timeout(5000)
    }
  );
  const data = await response.json();
  if (!response.ok || !data.ok) throw new Error("Bot API request failed");
  return data.result;
}

// Проверяем исходную initData, а не initDataUnsafe.
function telegramUser(raw) {
  const unauthorized = () =>
    Object.assign(new Error("Unauthorized"), { status: 401 });

  if (typeof raw !== "string") throw unauthorized();
  const params = new URLSearchParams(raw);
  if (new Set(params.keys()).size !== [...params.keys()].length)
    throw unauthorized();

  const hash = params.get("hash");
  if (!/^[a-f0-9]{64}$/i.test(hash ?? "")) throw unauthorized();
  params.delete("hash");

  // При HMAC-проверке signature, если присутствует, остаётся в строке.
  const check = [...params.entries()]
    .sort(([a], [b]) => a < b ? -1 : a > b ? 1 : 0)
    .map(([key, value]) => `${key}=${value}`)
    .join("\n");

  const secret = createHmac("sha256", "WebAppData")
    .update(TOKEN).digest();
  const expected = createHmac("sha256", secret).update(check).digest();

  if (!timingSafeEqual(expected, Buffer.from(hash, "hex")))
    throw unauthorized();

  const age = Date.now() / 1000 - Number(params.get("auth_date"));
  if (!Number.isFinite(age) || age < -30 || age > 3600)
    throw unauthorized(); // TTL 1 час — политика этого приложения.

  let user;
  try { user = JSON.parse(params.get("user")); }
  catch { throw unauthorized(); }

  if (!Number.isSafeInteger(user?.id) || user.id <= 0)
    throw unauthorized();

  return String(user.id);
}

app.post("/api/skin/invoice", route(async (req, res) => {
  const userId = telegramUser(req.body.initData);

  // Сохранить заказ до создания ссылки. Не брать цену/userId с клиента.
  const order = {
    id: randomUUID(),
    userId,
    sku: "premium_skin",
    currency: "XTR",
    amount: PRICE
  };
  await db.createOrder(order);

  const url = await bot("createInvoiceLink", {
    title: "Премиум-скин",
    description: "Премиум-скин для игры",
    payload: order.id,
    currency: "XTR",
    prices: [{ label: "Премиум-скин", amount: order.amount }]
    // provider_token для Stars не нужен.
  });

  res.json({ url });
}));

function matches(order, payment, userId) {
  return order &&
    order.userId === String(userId) &&
    order.sku === "premium_skin" &&
    order.currency === payment.currency &&
    order.amount === payment.total_amount;
}

app.post("/telegram/webhook", route(async (req, res) => {
  if (req.get("X-Telegram-Bot-Api-Secret-Token") !== WEBHOOK_SECRET)
    return res.sendStatus(403);

  const query = req.body.pre_checkout_query;
  if (query) {
    const order = await db.getOrder(query.invoice_payload);
    const ok = Boolean(
      matches(order, query, query.from.id) &&
      await db.canCheckout(order.id)
    );

    await bot("answerPreCheckoutQuery", {
      pre_checkout_query_id: query.id,
      ok,
      ...(!ok && { error_message: "Заказ недоступен. Обновите магазин." })
    });
  }

  const message = req.body.message;
  const payment = message?.successful_payment;
  if (payment) {
    await db.transaction(async tx => {
      const order = await tx.getOrderForUpdate(payment.invoice_payload);

      // Повторно проверяем всё внутри транзакции.
      if (!matches(order, payment, message.from.id))
        throw new Error("Payment does not match order");

      await tx.fulfillOnce({
        orderId: order.id,
        userId: order.userId,
        sku: order.sku,
        chargeId: payment.telegram_payment_charge_id
      });
    });
  }

  // Для оплаты отвечаем 200 только после успешной фиксации в БД.
  res.sendStatus(200);
}));

app.use((error, req, res, next) => {
  console.error(error.message);
  res.sendStatus(error.status ?? 500); // Telegram повторит webhook при 500.
});

app.listen(3000);
```

Контракт БД:

- `createOrder` сохраняет цену, валюту, товар и пользователя. `getOrder` возвращает их с `userId` в виде строки.
- `canCheckout` проверяет состояние заказа и доступность покупки, включая отсутствие уже купленного скина.
- `getOrderForUpdate` блокирует строку заказа.
- `fulfillOnce` **в одной транзакции** сохраняет платёж, помечает заказ оплаченным и добавляет скин в серверный инвентарь. Нужны уникальные ограничения на `chargeId` и `(userId, sku)`. Повтор того же платежа — успешная пустая операция; другое реальное списание требует учёта и возврата.

Webhook регистрируется серверным вызовом `setWebhook`:

```js
await bot("setWebhook", {
  url: "https://your-domain.example/telegram/webhook",
  secret_token: WEBHOOK_SECRET,
  allowed_updates: ["pre_checkout_query", "message"]
});
```

На `pre_checkout_query` нужно ответить за **10 секунд**. Скин выдаётся только после `successful_payment`; одобрение предварительной проверки ещё не означает оплату. [Порядок оплаты](https://core.telegram.org/bots/payments-stars#step-by-step-process).

Проверка пользователя основана на [подписи `initData`](https://core.telegram.org/bots/webapps#validating-data-received-via-the-mini-app). Сохранённый `telegram_payment_charge_id` понадобится для `refundStarPayment`; также предусмотрите команду `/paysupport`. [Возвраты и поддержка](https://core.telegram.org/bots/payments-stars#q-how-are-disputes-handled).
